correctedCode:
public class GradeCalculator {
    public static void main(String[] args) {
        int score = 95;
        String grade;
        if (score >= 90) {
            grade = "A";
        } else if (score >= 80) {
            grade = "B";
        } else if (score >= 70) {
            grade = "C";
        } else {
            grade = "F";
        }
        System.out.println(grade);
    }
}
